INSERT INTO public.maxims (
  id, latin_phrase, indonesian_meaning, literal_translation,
  pronunciation_guide, legal_fields, legal_meaning, history,
  is_active, status, difficulty, version_number, data,
  created_at, updated_at
) VALUES (
  'nullum-crimen',
  'Nullum Crimen Sine Lege',
  'Tidak ada suatu perbuatan dapat dipidana kecuali atas kekuatan aturan pidana dalam perundang-undangan yang telah ada sebelum perbuatan dilakukan',
  'Tidak ada kejahatan tanpa undang-undang',
  '/ˈnʊl.lʊm ˈkri.mɛn ˈsi.nɛ ˈle.ɡɛ/',
  ARRAY['pidana'],
  'Nullum Crimen Sine Lege (sering dilengkapi dengan Nulla Poena Sine Lege, yang berarti "tidak ada pidana tanpa undang-undang") adalah asas legalitas yang menjadi fondasi utama sistem hukum pidana modern. Asas ini menetapkan bahwa suatu perbuatan hanya dapat dianggap sebagai tindak pidana dan dikenai sanksi pidana jika perbuatan tersebut telah secara tegas dilarang dan diancam dengan pidana oleh peraturan perundang-undangan yang berlaku pada saat perbuatan tersebut dilakukan.

Fungsi utama dari asas ini adalah sebagai perisai pelindung bagi warga negara dari kesewenang-wenangan kekuasaan negara (arbitrariness of state power). Dengan mewajibkan adanya aturan tertulis yang jelas sebelum suatu perbuatan dilakukan, asas ini menjamin kepastian hukum (legal certainty) dan memberikan ruang bagi individu untuk mengatur perilakunya agar tidak melanggar hukum. Tanpa asas ini, negara berpotensi menghukum warga negaranya berdasarkan norma yang dibuat setelah perbuatan terjadi (retroactive law) atau berdasarkan penafsiran yang terlalu luas oleh aparat penegak hukum.

Ruang lingkup penerapan asas ini secara ketat dibatasi pada hukum pidana materiil. Dalam hukum pidana, asas ini melarang pemberlakuan hukum secara surut (retroactive), melarang penggunaan analogi untuk menciptakan delik baru (prohibition of analogy), dan mewajibkan perumusan delik yang jelas (lex certa). Hal ini berbeda dengan hukum perdata atau hukum administrasi, di mana analogi dan pemberlakuan surut dalam batas tertentu masih dimungkinkan.',
  'Sejarah asas Nullum Crimen Sine Lege dapat ditelusuri melalui tahapan berikut:

Romawi Kuno: Meskipun hukum Romawi tidak memiliki kodifikasi tunggal yang secara eksplisit merumuskan nullum crimen sine lege seperti modern, prinsip bahwa hukuman harus didasarkan pada hukum tertulis (ius scriptum) mulai berkembang, terutama dalam Lex Duodecim Tabularum (Hukum Dua Belas Tabel).

Magna Carta (1215): Pasal 39 Magna Carta menyatakan bahwa tidak ada orang bebas yang akan ditangkap, dipenjara, atau dihilangkan haknya kecuali oleh "hukum yang sah dari negeri tersebut" (lawful judgment of his peers or by the law of the land), yang menjadi cikal bakal perlindungan terhadap kesewenang-wenangan.

Pencerahan Eropa (Abad ke-18): Filosof Cesare Beccaria dalam karyanya Dei Delitti e Delle Pene (1764) menegaskan bahwa hanya undang-undang yang dapat menetapkan hukuman atas kejahatan, dan hakim tidak boleh menafsirkan undang-undang secara melampaui teksnya.

Revolusi Prancis (1789): Declaration of the Rights of Man and of the Citizen Pasal 8 secara eksplisit merumuskan: "Hukum hanya boleh menetapkan hukuman yang benar-benar dan jelas-jelas diperlukan, dan tidak ada seorang pun yang dapat dihukum kecuali berdasarkan hukum yang ditetapkan dan diundangkan sebelum perbuatan dilakukan."

Belanda dan Indonesia: Belanda mengadopsi asas ini dalam Pasal 1 Wetboek van Strafrecht (Sr.). Saat diberlakukan di Hindia Belanda, asas ini dibawa ke dalam Pasal 1 ayat (1) KUHP yang berlaku hingga saat ini dan diperkuat oleh konstitusi modern.',
  true,
  'stable',
  'menengah',
  1,
  '{"synonyms":["Asas Legalitas","Principle of Legality","Gesetzlichkeitsprinzip"],"usedIn":["Indonesia","Belanda","Jerman","Prancis","negara-negara yang meratifikasi ICCPR"],"classification":{"legalBranch":"Hukum Pidana Materiil dan Hukum Hak Asasi Manusia","nature":"Imperatif","applicationLevel":"Nasional dan Internasional","traditionSource":"Hukum Romawi, Magna Carta (1215), dan Declaration of the Rights of Man and of the Citizen (1789)"},"applicabilityStatus":{"validInIndonesia":true,"validInternationally":true,"recognizedByDoctrine":true,"codified":true,"notes":"Dikodifikasi dalam Pasal 1 ayat (1) KUHP dan Pasal 28I ayat (1) UUD 1945 sebagai non-derogable right"},"wordByWord":[{"word":"Nullum","meaning":"Tidak ada, tiada"},{"word":"Crimen","meaning":"Kejahatan, tindak pidana, dakwaan"},{"word":"Sine","meaning":"Tanpa"},{"word":"Lege","meaning":"Undang-undang, hukum tertulis"}],"wordByWordExtended":[{"word":"Nullum","latinForm":"Nullus, -a, -um","partOfSpeech":"Adjektiva (Netral, Akusatif)","meaning":"Tidak ada, tiada"},{"word":"Crimen","latinForm":"Crimen, criminis (n)","partOfSpeech":"Nomina (Akusatif)","meaning":"Kejahatan, tindak pidana, dakwaan"},{"word":"Sine","latinForm":"Sine","partOfSpeech":"Preposisi","meaning":"Tanpa"},{"word":"Lege","latinForm":"Lex, legis (f)","partOfSpeech":"Nomina (Ablatif)","meaning":"Undang-undang, hukum tertulis"}],"etymologyNotes":"Frasa ini merupakan klausa nominal yang menyatakan ketiadaan. Nullum Crimen berfungsi sebagai subjek dalam kasus Akusatif (\"tidak ada kejahatan\"), sedangkan Sine Lege adalah frasa preposisional menggunakan kasus Ablatif (\"tanpa undang-undang\"). Struktur ini menegaskan hubungan kondisional yang mutlak: kejahatan tidak dapat eksis secara yuridis tanpa keberadaan undang-undang yang mendahuluinya.","philosophicalMeaning":{"origin":"Asas ini lahir dari filosofi Rechtsstaat (Negara Hukum) yang menolak Machtstaat (Negara Kekuasaan). Warga negara harus dapat mengetahui dengan pasti apa yang dilarang dan apa konsekuensinya sebelum bertindak.","justiceValue":"Menghukum seseorang atas dasar aturan yang belum ada saat ia bertindak adalah bentuk ketidakadilan yang mendasar, karena orang tersebut tidak memiliki kesempatan untuk mematuhi hukum tersebut.","romanThought":"Prinsip bahwa hukuman harus didasarkan pada hukum tertulis (ius scriptum) mulai berkembang dalam hukum Romawi, terutama dalam Lex Duodecim Tabularum (Hukum Dua Belas Tabel).","modernRelevance":"Dalam masyarakat modern yang berubah cepat, asas ini menjadi semakin penting sebagai penyeimbang antara kebutuhan kriminalisasi perbuatan baru (siber, keuangan) dengan perlindungan hak individu."},"historyTimeline":[{"era":"Romawi Kuno","period":"Romawi Kuno","description":"Prinsip bahwa hukuman harus didasarkan pada hukum tertulis (ius scriptum) mulai berkembang dalam Lex Duodecim Tabularum."},{"era":"Magna Carta","period":"1215","description":"Pasal 39 Magna Carta melarang penangkapan dan penghukuman tanpa \"hukum yang sah dari negeri tersebut\". Cikal bakal perlindungan dari kesewenang-wenangan."},{"era":"Pencerahan Eropa","period":"Abad ke-18","description":"Cesare Beccaria dalam Dei Delitti e Delle Pene (1764) menegaskan hanya undang-undang yang dapat menetapkan hukuman dan hakim tidak boleh menafsirkan melampaui teks."},{"era":"Revolusi Prancis","period":"1789","description":"Declaration of the Rights of Man Pasal 8: tidak ada seorang pun dapat dihukum kecuali berdasarkan hukum yang ditetapkan sebelum perbuatan dilakukan."},{"era":"Belanda dan Indonesia","period":"Masa Kolonial","description":"Belanda mengadopsi asas ini dalam Pasal 1 Wetboek van Strafrecht, yang kemudian menjadi Pasal 1 ayat (1) KUHP Indonesia."},{"era":"Indonesia Pasca UUD 1945","period":"Modern","description":"Dikukuhkan dalam Pasal 28I ayat (1) UUD 1945 sebagai non-derogable right, dan dalam UU No. 12 Tahun 2005 ratifikasi ICCPR Pasal 15."}],"doctrineDevelopment":[{"era":"Doktrin Formalistik Klasik","description":"Asas ini ditafsirkan sangat kaku: hanya undang-undang tertulis (statute) yang dapat menjadi dasar pemidanaan, penafsiran analogi dilarang mutlak."},{"era":"Doktrin Lex Certa","description":"Perkembangan modern menambahkan persyaratan bahwa undang-undang harus jelas (clear) dan tegas (definite). UU yang terlalu kabur (vague) melanggar asas legalitas."},{"era":"Doktrin Hukum Internasional (Nuremberg)","description":"Pasca PD II, Piagam Nuremberg (1945) menciptakan pengecualian terbatas: kejahatan terhadap kemanusiaan dapat dihukum berdasarkan hukum kebiasaan internasional."},{"era":"Doktrin Living Law","description":"Dalam diskursus RKUHP Indonesia, muncul wacana bahwa hukum yang hidup dalam masyarakat dapat menjadi dasar pemidanaan, memicu perdebatan akademis tentang potensi penggerusan asas legalitas tertulis."}],"elements":["Adanya Perbuatan: Harus ada tindakan atau kelalaian yang dilakukan oleh subjek hukum.","Aturan Pidana Tertulis: Harus ada peraturan perundang-undangan yang secara eksplisit menyatakan perbuatan tersebut sebagai delik.","Ancaman Pidana: Peraturan tersebut harus memuat sanksi pidana yang jelas.","Kronologi Waktu: Peraturan perundang-undangan tersebut harus sudah ada dan berlaku secara sah sebelum perbuatan dilakukan."],"conditions":["Tertulis (Scripta): Sumber hukum pidana harus berbentuk peraturan perundang-undangan tertulis. Mencegah penghukuman berdasarkan hukum adat atau kebiasaan yang tidak tertulis dan tidak pasti.","Ada Sebelumnya (Praevia): Undang-undang harus sudah berlaku sebelum perbuatan dilakukan. Mencegah pemberlakuan hukum surut (retroactive) yang merugikan terdakwa.","Jelas dan Tegas (Certa): Rumusan delik dalam undang-undang harus jelas, tidak multitafsir, dan membatasi diskresi penegak hukum (fair warning)."],"exceptions":["Hukum Pidana Internasional: Berdasarkan Piagam Nuremberg dan Statuta Roma (ICC), pelaku genosida, kejahatan terhadap kemanusiaan, kejahatan perang dapat diadili berdasarkan hukum internasional (jus cogens).","Ketentuan Retroaktif Terbatas untuk Pelanggaran HAM Berat: Pasal 43 UU No. 26 Tahun 2000 memungkinkan pemberlakuan surut untuk pelanggaran HAM berat. MK dalam Putusan No. 065/PUU-II/2004 menyatakan hal ini dapat dibenarkan secara konstitusional.","Hukum yang Menguntungkan Terdakwa (Lex Mitior): Jika ada undang-undang baru yang lebih ringan atau menghapuskan pidana, undang-undang baru tersebut dapat berlaku surut untuk menguntungkan terdakwa."],"scope":{"applies":["Hukum Pidana Materiil (penentuan apakah suatu perbuatan adalah delik).","Penentuan jenis dan batas maksimal ancaman pidana.","Semua peraturan perundang-undangan yang memuat sanksi pidana (KUHP, UU Narkotika, UU Tipikor, UU ITE)."],"doesNotApply":["Hukum Perdata (analogi diperbolehkan untuk mengisi kekosongan hukum).","Hukum Administrasi Negara (dalam batas tertentu, prinsip legalitas lebih longgar).","Sanksi disiplin atau sanksi administratif (yang bukan merupakan pidana)."]},"legalBasisTable":[{"statute":"UUD 1945","article":"Pasal 28I ayat (1)","relevance":"Menjamin hak untuk tidak dituntut atas dasar hukum yang berlaku surut sebagai HAM non-derogable."},{"statute":"KUHP","article":"Pasal 1 ayat (1)","relevance":"\"Tiada suatu perbuatan dapat dipidana kecuali atas kekuatan aturan pidana dalam perundang-undangan yang telah ada sebelum perbuatan dilakukan.\""},{"statute":"KUHP","article":"Pasal 1 ayat (2)","relevance":"\"Jika ada perubahan dalam perundang-undangan sesudah perbuatan dilakukan, maka yang dipakai adalah ketentuan yang paling ringan bagi terdakwa.\" (Lex Mitior)."},{"statute":"UU No. 39 Tahun 1999","article":"Pasal 47","relevance":"\"Hak untuk tidak dituntut atas dasar hukum yang berlaku surut adalah hak asasi manusia yang tidak dapat dikurangi dalam keadaan apa pun.\""},{"statute":"UU No. 12 Tahun 2005","article":"Pasal 15 ICCPR","relevance":"Meratifikasi kewajiban internasional untuk tidak memberlakukan hukum pidana secara surut, kecuali untuk perbuatan yang sudah merupakan kejahatan menurut prinsip umum hukum internasional."},{"statute":"UU No. 26 Tahun 2000","article":"Pasal 43","relevance":"Mengatur pengecualian retroaktif untuk pelanggaran HAM berat, yang diuji dan diputuskan MK dalam Putusan No. 065/PUU-II/2004."}],"indonesianLegalBasis":"Pasal 1 ayat (1) KUHP dan Pasal 28I ayat (1) UUD 1945 sebagai non-derogable right.","indonesianSystemRelation":"Bagi Hakim: terikat mutlak pada Pasal 1 ayat (1) KUHP, dilarang menggunakan analogi in malam partem untuk memperluas cakupan delik. Bagi Legislator: wajib merumuskan delik-delik baru dengan bahasa yang jelas (lex certa) dan menghindari rumusan terlalu elastis. Bagi Akademisi: objek kajian kritis terutama dalam menanggapi fenomena overcriminalization dan wacana living law dalam RKUHP.","normativeExamples":["KUHP Pasal 338: \"Barangsiapa sengaja merampas nyawa orang lain, diancam karena pembunuhan, dengan pidana penjara paling lama lima belas tahun.\" Penerapan lex certa dan nullum crimen sine lege.","UU ITE Pasal 27 ayat (3) UU No. 19 Tahun 2016: Merumuskan delik pencemaran nama baik secara spesifik di ranah elektronik, memberikan dasar hukum tertulis yang sebelumnya tidak ada di KUHP untuk konteks siber.","UU Tipikor Pasal 2 dan 3 UU No. 31 Tahun 1999 jo. UU No. 20 Tahun 2001: Merumuskan unsur-unsur korupsi secara khusus sebagai dasar hukum pemidanaan yang mengesampingkan ketentuan penggelapan biasa dalam KUHP."],"practicalExamples":["Kasus Perbuatan yang Belum Diatur: Seseorang melakukan perbuatan yang secara sosial dianggap tercela, namun belum ada satu pun pasal dalam UU yang secara spesifik melarang dan mengancamnya dengan pidana. Berdasarkan asas ini, polisi tidak dapat menahannya dan jaksa tidak dapat mendakwanya.","Penerapan Lex Mitior: Seseorang melakukan tindak pidana pada tahun 2020. Pada tahun 2022, UU diubah dan ancaman pidananya diturunkan. Saat diadili pada tahun 2023, hakim wajib menerapkan UU tahun 2022 yang lebih ringan.","Penolakan Analogi: Hakim tidak boleh menghukum seseorang untuk \"pencurian listrik\" dengan menggunakan analogi pasal \"pencurian barang\" jika pada saat itu belum ada ketentuan khusus yang memasukkan aliran listrik sebagai \"barang\" yang dapat dicuri."],"jurisprudence":[{"id":"mk-065-2004","courtName":"Mahkamah Konstitusi","caseNumber":"No. 065/PUU-II/2004","year":2004,"date":"2004","context":"Pengujian Pasal 43 UU No. 26/2000 tentang Retroaktivitas HAM","excerpt":"MK menyatakan bahwa pemberlakuan surut untuk pelanggaran HAM berat dapat dibenarkan secara konstitusional sebagai pengecualian terbatas, namun menegaskan bahwa untuk tindak pidana biasa, asas non-retroaktif adalah mutlak.","summary":"Menegaskan batas dan pengecualian sempit dari asas legalitas dalam konteks HAM berat.","analysis":"Putusan ini mengakui dualitas: asas nullum crimen sine lege adalah mutlak untuk pidana biasa, namun pengecualian terbatas dibenarkan untuk kejahatan luar biasa (extraordinary crimes) berdasarkan jus cogens internasional.","sourceUrl":"https://www.mkri.id"},{"id":"mk-135-2009","courtName":"Mahkamah Konstitusi","caseNumber":"No. 135/PUU-VII/2009","year":2010,"date":"2010","context":"Pengujian pasal-pasal pidana terkait kepastian hukum","excerpt":"MK menekankan pentingnya asas kepastian hukum (legal certainty) dan lex certa dalam perumusan delik, agar tidak multitafsir dan melanggar hak konstitusional warga negara.","summary":"Menguatkan dimensi Lex Certa sebagai turunan dari Nullum Crimen Sine Lege.","analysis":"Menunjukkan bahwa asas nullum crimen sine lege tidak hanya mensyaratkan ada tidaknya aturan, tetapi juga kejelasan dan ketegasan rumusannya (lex certa).","sourceUrl":"https://www.mkri.id"},{"id":"ma-yurisprudensi-no","courtName":"Mahkamah Agung","caseNumber":"Yurisprudensi Tetap","year":0,"date":"Berbagai Tahun","context":"Penolakan Dakwaan (Niet Ontvankelijke Verklaard)","excerpt":"Hakim secara konsisten menyatakan dakwaan Niet Ontvankelijke Verklaard (NO) jika perbuatan terdakwa terjadi sebelum UU yang didakwakan diundangkan.","summary":"Penerapan praktis murni dari Pasal 1 ayat (1) KUHP di tingkat pengadilan.","analysis":"Penerapan langsung asas nullum crimen sine lege dalam praktik peradilan: tanpa aturan yang ada sebelumnya, dakwaan tidak dapat diterima.","sourceUrl":"https://www.mahkamahagung.go.id"}],"caseExamples":[],"internationalComparisons":[{"country":"Belanda","status":"Dikenal","description":"Pasal 1 Wetboek van Strafrecht (Sr.) merumuskan asas ini secara identik dengan KUHP Indonesia. Belanda sangat ketat dalam melarang analogi yang merugikan terdakwa."},{"country":"Jerman","status":"Dikenal","description":"Grundgesetz (Konstitusi) Pasal 103 ayat (2): \"Suatu perbuatan hanya dapat dihukum jika perbuatan tersebut telah diancam dengan pidana oleh undang-undang sebelum perbuatan tersebut dilakukan.\" Sangat menekankan nulla poena sine lege."},{"country":"Prancis","status":"Dikenal","description":"Declaration of the Rights of Man (1789) Pasal 8 adalah salah satu rumusan tertulis pertama di dunia modern yang melarang hukum surut dalam pidana."},{"country":"Inggris","status":"Dikenal Sebagian","description":"Sebagai negara Common Law, prinsip Rule of Law (A.V. Dicey) melarang hukuman sewenang-wenang. Namun, Inggris secara historis lebih fleksibel terhadap judge-made law."},{"country":"Amerika Serikat","status":"Dikenal","description":"Konstitusi AS Pasal 1 Ayat 9 dan 10 melarang Ex Post Facto Laws (hukum yang berlaku surut) baik di tingkat federal maupun negara bagian."}],"maximComparisons":[{"maximId":"nulla-poena-sine-lege","latinPhrase":"Nulla Poena Sine Lege","whenUsed":"Pasangan yang tak terpisahkan. Nullum crimen melindungi dari kriminalisasi perbuatan, nulla poena melindungi dari penjatuhan hukuman yang tidak diatur UU."},{"maximId":"lex-certa","latinPhrase":"Lex Certa","whenUsed":"Merupakan turunan atau syarat penerapan dari Nullum Crimen Sine Lege. UU yang ada tapi tidak jelas (vague) dianggap melanggar asas legalitas."},{"maximId":"lex-posterior","latinPhrase":"Lex Posterior Derogat Legi Priori","whenUsed":"Dalam hukum pidana, Lex Posterior hanya berlaku jika menguntungkan terdakwa (Lex Mitior). Jika hukum baru lebih berat, dilarang berlaku surut."},{"maximId":"ne-bis-in-idem","latinPhrase":"Ne Bis In Idem","whenUsed":"Nullum crimen melindungi dari hukuman tanpa dasar hukum. Ne Bis In Idem melindungi dari penuntutan atau penghukuman dua kali untuk perbuatan yang sama."}],"analysis":{"purpose":"Melindungi warga negara dari kesewenang-wenangan negara dan menjamin kepastian hukum.","protectedValues":"Kebebasan individu, keadilan prosedural, dan supremasi hukum tertulis.","advantages":"Menciptakan batasan yang jelas bagi kekuasaan negara dan memberikan rasa aman bagi masyarakat dalam bertindak.","critique":"Dalam masyarakat modern yang berubah cepat (kejahatan siber, kejahatan keuangan kompleks), asas ini terkadang dianggap terlalu kaku. Legislator sering tertinggal sehingga muncul celah hukum (loophole).","limitations":"Tergantung pada kualitas perumusan undang-undang. Jika legislator merumuskan delik terlalu luas, asas ini menjadi tidak efektif karena hakim tetap memiliki ruang diskresi yang besar."},"scholarViews":[{"name":"Prof. Dr. Moeljatno, S.H.","view":"Pasal 1 ayat (1) KUHP adalah penjabaran dari asas nullum crimen sine lege. Asas ini bertujuan untuk memberikan kepastian hukum bagi warga negara dan membatasi kekuasaan hakim dalam menciptakan hukum baru melalui penafsiran analogi.","source":"Asas-Asas Hukum Pidana (2008)"},{"name":"Prof. Dr. Andi Hamzah, S.H.","view":"Asas legalitas tidak hanya mensyaratkan adanya undang-undang, tetapi juga undang-undang tersebut harus sudah ada sebelum perbuatan dilakukan. Larangan analogi adalah konsekuensi logis yang mutlak dari asas ini dalam hukum pidana.","source":"Asas-Asas Hukum Pidana di Indonesia"},{"name":"Prof. Dr. Romli Atmasasmita, S.H., LL.M.","view":"Pengakuan terhadap living law (hukum yang hidup dalam masyarakat) dalam RKUHP harus dibatasi secara ketat agar tidak menggerus esensi dari nullum crimen sine lege yang mensyaratkan kepastian hukum tertulis.","source":"Teori dan Kapita Selekta Kriminologi (2016)"}],"controversies":[{"title":"Penerapan Retroaktif UU HAM","description":"Pasal 43 UU No. 26 Tahun 2000 mengizinkan pengadilan HAM untuk mengadili pelanggaran HAM berat yang terjadi sebelum UU ini disahkan. Sebagian ahli berpendapat ini adalah pelanggaran Pasal 28I UUD 1945, sementara pihak lain berargumen ini adalah pengecualian yang dibenarkan hukum internasional (jus cogens)."},{"title":"Living Law dalam RKUHP","description":"Wacana pengakuan hukum yang hidup dalam masyarakat (living law) sebagai dasar pemidanaan dalam Rancangan KUHP memicu perdebatan sengit antara akademisi yang menilai ini menggerus asas legalitas formal dengan mereka yang menganggapnya sebagai akomodasi realitas hukum adat."}],"commonMistakes":[{"misconception":"\"Asas ini berlaku di semua bidang hukum.\"","fact":"Salah. Asas ini secara ketat hanya berlaku di Hukum Pidana. Di hukum perdata, analogi dan pemberlakuan surut dalam batas tertentu diperbolehkan."},{"misconception":"\"Hakim boleh menggunakan analogi jika perbuatannya jelas jahat.\"","fact":"Salah. Dalam hukum pidana, analogi yang merugikan terdakwa (in malam partem) dilarang mutlak, seberapa pun tercelanya perbuatan tersebut, jika tidak diatur dalam UU."},{"misconception":"\"UU baru selalu bisa menghukum perbuatan masa lalu.\"","fact":"Salah. UU baru hanya bisa berlaku surut jika menguntungkan terdakwa (lex mitior). Jika memberatkan, dilarang mutlak."}],"faq":[{"question":"Apakah Nullum Crimen Sine Lege berarti hukum adat tidak bisa dipakai untuk menghukum?","answer":"Ya, dalam hukum pidana nasional positif, hukum adat yang tidak tertulis tidak dapat menjadi dasar pemidanaan langsung, kecuali jika nilai-nilainya telah diakomodasi ke dalam peraturan perundang-undangan tertulis."},{"question":"Bagaimana jika suatu perbuatan sangat jahat tapi belum ada UU yang mengaturnya?","answer":"Perbuatan tersebut tidak dapat dipidana. Ini adalah konsekuensi dari rule of law. Solusinya adalah legislator harus segera membuat UU baru untuk masa depan, bukan menghukum pelaku saat ini secara surut."},{"question":"Apakah Peraturan Pemerintah (PP) bisa menciptakan delik pidana baru?","answer":"Tidak. Berdasarkan asas legalitas dan hierarki peraturan, ancaman pidana harus diatur dalam Undang-Undang (UU). PP hanya dapat mengatur sanksi administratif, kecuali diberi delegasi yang sangat spesifik dan terbatas oleh UU induk."},{"question":"Apa bedanya Nullum Crimen Sine Lege dengan Ne Bis In Idem?","answer":"Nullum Crimen melindungi dari hukuman tanpa dasar hukum. Ne Bis In Idem melindungi dari penuntutan atau penghukuman dua kali untuk perbuatan yang sama."},{"question":"Apakah asas ini melindungi korporasi?","answer":"Ya. Jika suatu UU tidak secara eksplisit mengatur pertanggungjawaban pidana korporasi, maka korporasi tidak dapat dipidana, meskipun pengurusnya bisa saja dipidana berdasarkan ketentuan untuk orang pribadi."}],"maximNotes":"Dalam praktik penyidikan, polisi sering kali menggunakan pasal yang tidak tepat karena tekanan untuk menyelesaikan kasus. Penting bagi penasihat hukum untuk segera memeriksa kronologi waktu perbuatan vs tanggal pengundangan UU untuk memastikan asas ini tidak dilanggar. Asas ini juga berlaku untuk sanksi pidana dalam UU Sektoral, bukan hanya KUHP.","relatedTerms":[{"term":"Nulla Poena Sine Lege","definition":"Tidak ada pidana tanpa undang-undang — pasangan dari Nullum Crimen."},{"term":"Lex Certa","definition":"Asas kepastian perumusan delik — delik harus dirumuskan dengan jelas."},{"term":"Retroactive Law","definition":"Hukum yang berlaku surut — dilarang mutlak jika merugikan terdakwa."},{"term":"Non-Derogable Rights","definition":"Hak yang tidak dapat dikurangi dalam keadaan apapun."},{"term":"Analogi","definition":"Penafsiran dengan persamaan dasar — dilarang dalam hukum pidana (in malam partem)."},{"term":"Overcriminalization","definition":"Inflasi hukum pidana — terlalu banyak perbuatan yang dikriminalisasi."},{"term":"Living Law","definition":"Hukum yang hidup dalam masyarakat — masih diperdebatkan penggunaannya sebagai dasar pidana."},{"term":"Lex Mitior","definition":"Hukum yang lebih ringan — UU baru yang lebih ringan dapat berlaku surut untuk keuntungan terdakwa."},{"term":"Rechtsstaat","definition":"Negara Hukum — negara yang tunduk pada aturan hukum, bukan kekuasaan belaka."},{"term":"Jus Cogens","definition":"Norma hukum internasional yang memaksa — dasar pengecualian untuk kejahatan luar biasa."}],"relations":[{"id":"ne-bis-in-idem","latinPhrase":"Ne Bis In Idem","indonesianMeaning":"Tidak boleh diadili dua kali untuk perkara yang sama","relationType":"terkait"},{"id":"nulla-poena-sine-lege","latinPhrase":"Nulla Poena Sine Lege","indonesianMeaning":"Tidak ada pidana tanpa undang-undang","relationType":"sinonim"},{"id":"in-dubio-pro-reo","latinPhrase":"In Dubio Pro Reo","indonesianMeaning":"Dalam keraguan, menguntungkan terdakwa","relationType":"hierarkis"}],"references":{"primary":{"constitutions":["Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Pasal 28I ayat (1)."],"statutes":["Kitab Undang-Undang Hukum Pidana (KUHP), Pasal 1 ayat (1) dan (2).","Undang-Undang Nomor 39 Tahun 1999 tentang Hak Asasi Manusia, Pasal 47.","Undang-Undang Nomor 12 Tahun 2005 tentang Pengesahan International Covenant on Civil and Political Rights (ICCPR).","Undang-Undang Nomor 26 Tahun 2000 tentang Pengadilan Hak Asasi Manusia, Pasal 43."],"rulings":["Putusan Mahkamah Konstitusi No. 065/PUU-II/2004.","Putusan Mahkamah Konstitusi No. 135/PUU-VII/2009."]},"secondary":{"books":["Moeljatno. (2008). Asas-Asas Hukum Pidana. Jakarta: Rineka Cipta.","Hamzah, Andi. (2017). Asas-Asas Hukum Pidana. Jakarta: Rineka Cipta.","Atmasasmita, Romli. (2016). Teori dan Kapita Selekta Kriminologi. Bandung: Refika Aditama.","Simanjuntak, E.U.T. Kebijakan Hukum Pidana.","Kartanegara, Satochid. Kumpulan Karangan Hukum."],"journals":["Jurnal Hukum Pidana dan Kriminologi. Artikel mengenai \"Asas Legalitas dan Tantangan Living Law\".","Constitutional Review. Analisis putusan MK terkait hak atas kepastian hukum."]},"tertiary":{"encyclopedias":["Mahkamah Konstitusi Republik Indonesia. Putusan No. 065/PUU-II/2004 dan No. 135/PUU-VII/2009.","Badan Pembinaan Hukum Nasional (BPHN). Naskah Akademik dan Konsep RKUHP."]}},"furtherReading":[{"title":"Asas-Asas Hukum Pidana","author":"Moeljatno","type":"buku"},{"title":"Asas-Asas Hukum Pidana di Indonesia","author":"Andi Hamzah","type":"buku"},{"title":"Kebijakan Hukum Pidana","author":"E.U.T. Simanjuntak","type":"buku"},{"title":"Jurnal Hukum Pidana dan Kriminologi","author":"Berbagai Penulis","type":"jurnal"},{"title":"Constitutional Review","author":"Mahkamah Konstitusi","type":"jurnal"}],"meta":{"categories":["Asas Hukum","Hukum Pidana","Hak Asasi Manusia"],"portals":["Ilmu Hukum","Keadilan Pidana"],"tags":["Nullum Crimen Sine Lege","Asas Legalitas","Pasal 1 KUHP","Non-Retroaktif","Lex Certa","Hak Asasi Manusia"]}}'::jsonb,
